-- Standalone disposable database fixture; never run in an application database.
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
 SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid
$$;
CREATE TABLE public.organizations(id bigint PRIMARY KEY,title text);
CREATE TABLE public.occasions(id bigint PRIMARY KEY,organization bigint);
CREATE SCHEMA extensions;
CREATE EXTENSION unaccent WITH SCHEMA extensions;
REVOKE ALL ON SCHEMA extensions FROM PUBLIC,authenticated;
CREATE FUNCTION public.f_unaccent(t text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT SET search_path=public,extensions AS $$
 SELECT lower(extensions.unaccent('extensions.unaccent'::regdictionary,t))
$$;
CREATE TABLE public.news(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 occasion bigint,message text,created_by uuid,
 search_doc text GENERATED ALWAYS AS (public.f_unaccent(message)) STORED);
ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.get_is_editor_on_occasion(bigint) RETURNS boolean
LANGUAGE sql STABLE AS $$ SELECT auth.uid()='00000000-0000-0000-0000-000000000001'::uuid $$;
CREATE POLICY "Enable insert for editors" ON public.news FOR INSERT
TO authenticated WITH CHECK(public.get_is_editor_on_occasion(occasion));
CREATE POLICY news_read ON public.news FOR SELECT USING(true);
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT SELECT ON public.news,public.occasions TO authenticated;
GRANT USAGE ON SEQUENCE public.news_id_seq TO authenticated;
INSERT INTO public.organizations VALUES(19,'Slunovrat'),(1,'Other');
INSERT INTO public.occasions VALUES(101,19),(102,1);
\ir ../../../supabase/migrations/20261013093000_slunovrat_news_insert.sql
\ir ../../../supabase/migrations/20261013094500_news_search_extensions_usage.sql
\ir ../../../supabase/migrations/20261013100000_verify_news_search_schema_grant.sql
BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
INSERT INTO public.news(occasion,message,created_by)
VALUES(101,'Novinka bez oznámení',auth.uid()) RETURNING id;
DO $$ BEGIN
 IF (SELECT search_doc FROM public.news) <> 'novinka bez oznameni' THEN
  RAISE EXCEPTION 'generated news search column failed';
 END IF;
END $$;
DO $$ BEGIN
 BEGIN
  INSERT INTO public.news(occasion,message,created_by) VALUES(102,'other tenant',auth.uid());
  RAISE EXCEPTION 'other tenant accepted';
 EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN
  INSERT INTO public.news(occasion,message,created_by) VALUES(101,'spoofed author','00000000-0000-0000-0000-000000000002');
  RAISE EXCEPTION 'spoofed author accepted';
 EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN
  INSERT INTO public.news(id,occasion,message,created_by) VALUES(500,101,'explicit id',auth.uid());
  RAISE EXCEPTION 'explicit id accepted';
 EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
 BEGIN
  INSERT INTO public.news(occasion,message,created_by) VALUES(101,'non editor',auth.uid());
  RAISE EXCEPTION 'non editor accepted';
 EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
ROLLBACK;
